import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const o="/dev-notes/assets/house-angularity-chart.ZKd1gO3O.png",b=JSON.parse('{"title":"Nhà góc, nhà kế, nhà cuối (Angular, Succedent, Cadent)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/houses/angularity.md","filePath":"astro/houses/angularity.md"}'),c={name:"astro/houses/angularity.md"};function g(u,n,e,r,l,d){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="nha-goc-nha-ke-nha-cuoi-angular-succedent-cadent" tabindex="-1">Nhà góc, nhà kế, nhà cuối (Angular, Succedent, Cadent) <a class="header-anchor" href="#nha-goc-nha-ke-nha-cuoi-angular-succedent-cadent" aria-label="Permalink to &quot;Nhà góc, nhà kế, nhà cuối (Angular, Succedent, Cadent)&quot;">​</a></h1><p><img src="'+o+'" alt="Angular, Succedent, Cadent trên biểu đồ 12 nhà"></p><p>◼ NHÀ GÓC (ANGULAR HOUSE) – 1, 4, 7, 10 Các Nhà góc trong biểu đồ sinh của bạn nổi bật trong việc hướng đến hành động, vì chúng là Nhà chủ của các cung Tiên phong (Bạch Dương, Cự Giải, Thiên Bình và Ma Kết). Nếu nhiều hành tinh trong biểu đồ sinh của bạn rơi vào các Nhà này, bạn là người trội Nhà góc, được biết đến với khả năng khởi xướng, dẫn dắt và bắt đầu mọi việc. ◼ NHÀ KẾ (SUCCEDENT HOUSE) – 2, 5, 8, 11 Các Nhà kế trong biểu đồ sinh của bạn nổi bật với tính kiên định và vững vàng, vì chúng là Nhà chủ của các cung Kiên định (Kim Ngưu, Sư Tử, Bọ Cạp và Bảo Bình). Nếu nhiều hành tinh trong biểu đồ sinh của bạn rơi vào các Nhà này, bạn là người trội Nhà kế, được biết đến với tính cách ổn định, đáng tin cậy. Khi đã nhận trách nhiệm, bạn sẽ toàn tâm toàn ý với nó và luôn biết cách hoàn thành công việc. ◼ NHÀ CUỐI (CADENT HOUSE) – 3, 6, 9, 12 Các Nhà cuối trong biểu đồ sinh của bạn nổi bật với tính linh hoạt và dễ thích nghi, vì chúng là Nhà chủ của các cung Linh hoạt (Song Tử, Xử Nữ, Nhân Mã và Song Ngư). Nếu nhiều hành tinh trong biểu đồ sinh của bạn rơi vào các Nhà này, bạn là người trội Nhà cuối, được biết đến với khả năng thích nghi nhanh chóng, cởi mở với những thay đổi và luôn luôn trong trạng thái hoạt động.</p><p>Gần đúng, nhưng có ba chỗ nên chỉnh lại cho chính xác.</p><h2 id="_1-angular-khong-đong-nghia-voi-tot" tabindex="-1">1. Angular không đồng nghĩa với &quot;tốt&quot; <a class="header-anchor" href="#_1-angular-khong-đong-nghia-voi-tot" aria-label="Permalink to &quot;1. Angular không đồng nghĩa với &quot;tốt&quot;&quot;">​</a></h2><p>Angular chỉ làm hành tinh biểu hiện <strong>nhiều và rõ</strong>. Tốt hay xấu vẫn do dignity và condition quyết định. Ví dụ:</p><table tabindex="0"><thead><tr><th></th><th>Sun condition tốt (ví dụ ở Leo)</th><th>Sun condition xấu (ví dụ ở Libra, fall)</th></tr></thead><tbody><tr><td>Angular</td><td>Tỏa sáng rõ, được công nhận ngay</td><td>Cái yếu cũng lộ rõ, khó giấu</td></tr><tr><td>Cadent</td><td>Vẫn tốt nhưng kín đáo, ít người thấy</td><td>Vấn đề có nhưng ít bộc lộ</td></tr></tbody></table><p>Nên cách nói chính xác là: angular là <strong>khuếch đại</strong> (cả mặt tốt lẫn mặt xấu), cadent là <strong>thu nhỏ</strong>.</p><h2 id="_2-đung-goi-la-suc-manh-con-20" tabindex="-1">2. Đừng gọi là &quot;sức mạnh còn 20%&quot; <a class="header-anchor" href="#_2-đung-goi-la-suc-manh-con-20" aria-label="Permalink to &quot;2. Đừng gọi là &quot;sức mạnh còn 20%&quot;&quot;">​</a></h2><p>Bài viết nói:</p><ul><li>Angular: khoảng 100%</li><li>Succedent: khoảng 50–75%</li><li>Cadent: khoảng 25–50%</li></ul><p>Đây là hình ảnh ví von về &quot;âm lượng&quot; của tác giả bài, không phải số đo thật, và cadent là 25–50% chứ không phải 20%. Bạn đừng dùng con số này khi nói với khách. Chỉ nên nói &quot;ít biểu hiện hơn, kín đáo hơn&quot;.</p><h2 id="_3-no-đo-luong-bieu-hien-khong-phai-suc-manh-ben-trong" tabindex="-1">3. Nó đo &quot;lượng biểu hiện&quot;, không phải &quot;sức mạnh bên trong&quot; <a class="header-anchor" href="#_3-no-đo-luong-bieu-hien-khong-phai-suc-manh-ben-trong" aria-label="Permalink to &quot;3. Nó đo &quot;lượng biểu hiện&quot;, không phải &quot;sức mạnh bên trong&quot;&quot;">​</a></h2><p>Bài phân biệt rõ:</p><ul><li>Dignity (sign, phase, aspect) quyết định <strong>chất lượng</strong>.</li><li>Angularity (house) quyết định <strong>số lượng</strong>.</li></ul><p>Sun ở cadent không phải bị &quot;yếu đi bản chất&quot;, mà là nó ít có dịp thể hiện ra bên ngoài. Giống một người giỏi nhưng ngồi ở góc phòng họp: năng lực vẫn còn, chỉ là ít được nghe thấy.</p><h2 id="cau-tom-gon-đe-ban-ghi-vao-note" tabindex="-1">Câu tóm gọn để bạn ghi vào note <a class="header-anchor" href="#cau-tom-gon-đe-ban-ghi-vao-note" aria-label="Permalink to &quot;Câu tóm gọn để bạn ghi vào note&quot;">​</a></h2><p>Hành tinh ở angular thì hoạt động nhiều, rõ, dễ thấy nhất (khuếch đại cả tốt lẫn xấu). Ở succedent thì mức vừa. Ở cadent thì kín đáo, ít biểu hiện. Chất lượng tốt/xấu vẫn do dignity quyết định.</p><p>Bạn muốn mình gom lại thành <code>note_7.md</code> luôn không?</p>',19)])])}const v=t(c,[["render",g]]);export{b as __pageData,v as default};
